func (q *Queries) MarkEmailActionProposalFailed(ctx context.Context, arg MarkEmailActionProposalFailedParams) (MessagingEmailActionProposal, error) {
	row := q.db.QueryRow(ctx, markEmailActionProposalFailed,
		arg.Result,
		arg.LastError,
		arg.Now,
		arg.ProposalID,
		arg.ApplyAttempt,
	)
	var i MessagingEmailActionProposal
	err := row.Scan(
		&i.ID,
		&i.ThreadID,
		&i.WorkspaceID,
		&i.UserID,
		&i.SourceMessageID,
		&i.IdempotencyKey,
		&i.ActionKind,
		&i.EntityType,
		&i.EntityID,
		&i.ExpectedEntityVersion,
		&i.ProposedDiff,
		&i.Status,
		&i.ApplyAttempt,
		&i.Result,
		&i.LastError,
		&i.ExpiresAt,
		&i.ConfirmedAt,
		&i.ApplyingAt,
		&i.AppliedAt,
		&i.FailedAt,
		&i.CancelledAt,
		&i.ExpiredAt,
		&i.SupersededAt,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

const supersedePendingEmailProposals = `-- name: SupersedePendingEmailProposals :exec
UPDATE messaging_email_action_proposals
SET status = CASE WHEN expires_at <= $1 THEN 'expired' ELSE 'superseded' END,
    expired_at = CASE WHEN expires_at <= $1 THEN $1 ELSE NULL END,
    superseded_at = CASE WHEN expires_at > $1 THEN $1 ELSE NULL END,
    updated_at = NOW()
WHERE thread_id = $2
  AND status = 'pending'
`

type SupersedePendingEmailProposalsParams struct {
	Now      time.Time
	ThreadID uuid.UUID
}

func (q *Queries) SupersedePendingEmailProposals(ctx context.Context, arg SupersedePendingEmailProposalsParams) error {
	_, err := q.db.Exec(ctx, supersedePendingEmailProposals, arg.Now, arg.ThreadID)
	return err
}

const transitionEmailActionProposalDecision = `-- name: TransitionEmailActionProposalDecision :execrows
UPDATE messaging_email_action_proposals
SET status = $1,
    confirmed_at = CASE WHEN $1 = 'confirmed' THEN $2 ELSE confirmed_at END,
    cancelled_at = CASE WHEN $1 = 'cancelled' THEN $2 ELSE cancelled_at END,
    expired_at = CASE WHEN $1 = 'expired' THEN $2 ELSE expired_at END,
    superseded_at = CASE WHEN $1 = 'superseded' THEN $2 ELSE superseded_at END,
    updated_at = NOW()
WHERE id = $3
  AND status = 'pending'
`

type TransitionEmailActionProposalDecisionParams struct {
	Status     string
	Now        *time.Time
	ProposalID uuid.UUID
}

func (q *Queries) TransitionEmailActionProposalDecision(ctx context.Context, arg TransitionEmailActionProposalDecisionParams) (int64, error) {
	result, err := q.db.Exec(ctx, transitionEmailActionProposalDecision, arg.Status, arg.Now, arg.ProposalID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
